const cmds=[
["nodes","\"$HORIZON_BIN\" graph list --match 'divisor\\|stalk\\|support' --type lean --json --limit 100"],
["tex","\"$HORIZON_BIN\" graph list --type tex --lean-status lean_ok --json --limit 30"],
["inboxmine","\"$HORIZON_BIN\" inbox list --mine --unread --json --comments 1 --limit 20"],
["protection","\"$HORIZON_BIN\" inbox list --mine --status open --kind protection --json --comments 1"],
["issues","\"$HORIZON_BIN\" inbox list --project Hartshorne --kind issue --status open --json --comments 1"]
];
const out=await Promise.all(cmds.map(async([n,c])=>[n,await tools.exec_command({cmd:c,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:12000})]));
out.forEach(([n,r])=>text(`===${n} exit=${r.exit_code} session=${r.session_id||""}===\n${r.output}`));

const cmds=[
["sync","\"$HORIZON_BIN\" graph -p Hartshorne sync 2>&1 | tail -35"],
["match","\"$HORIZON_BIN\" graph --project Hartshorne list --type lean --match support --json --limit 30"],
["texok","\"$HORIZON_BIN\" graph --project Hartshorne list --type tex --lean-status lean_ok --json --limit 30"],
["inboxissues","\"$HORIZON_BIN\" inbox list --project Hartshorne --kind issue --status open --json --comments 0 | rg '\"id\"|\"title\"|\"body\"' | head -80"]
];
const out=await Promise.all(cmds.map(async([n,c])=>[n,await tools.exec_command({cmd:c,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:30000,max_output_tokens:7000})]));
out.forEach(([n,r])=>text(`===${n} exit=${r.exit_code}===\n${r.output}`));

const cmds = [
  ["graph", `"$HORIZON_BIN" graph -p Hartshorne frontier --json`],
  ["scoped", `"$HORIZON_GIT" status --short --untracked-files=all -- FormalizedSources/Curves/Hartshorne`],
  ["trackedvolatile", `"$HORIZON_GIT" ls-files | awk 'BEGIN{n=0} /(^|\\/)\\.(tmp|lock|trace)$|(^|\\/)(staging|scratch|attempts)(\\/|$)/{n++} END{print n}'`],
  ["hart_hidden", `find . -maxdepth 3 -type f -name '.*' -printf '%p\\n' | sort`],
  ["session_artifacts", `find "$ARCHON_HORIZON_SESSION_DIR" -maxdepth 2 -type f -printf '%P\\n' | sort`]
];
const rs = await Promise.all(cmds.map(([name,cmd])=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/FormalizedSources/Curves/Hartshorne",yield_time_ms:10000,max_output_tokens:7000})));
rs.forEach((r,i)=>text(`--- ${cmds[i][0]} ---\n${r.output}`));

const cmds = [
  ["graph_counts", `"$HORIZON_BIN" graph -p Hartshorne frontier --json | jq '{total:length,by_lean:(group_by(.lean_status)|map({status:.[0].lean_status,count:length})),top:(.[0:5]|map({id,title,lean_status,state,unlocks}))}'`],
  ["scoped2", `"$HORIZON_GIT" status --short --untracked-files=all -- HartshorneLib blueprint hgraph README.md`],
  ["queue_counts", `"$HORIZON_BIN" task list --json | jq '{warnings,counts:(.tasks|group_by(.status)|map({status:.[0].status,count:length})),hartshorne:(.tasks|map(select(.id=="fs-hartshorne"))|map({id,status,roadmap_refs}))}'`]
];
const rs = await Promise.all(cmds.map(([name,cmd])=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/FormalizedSources/Curves/Hartshorne",yield_time_ms:10000,max_output_tokens:5000})));
rs.forEach((r,i)=>text(`--- ${cmds[i][0]} ---\n${r.output}`));

